// Mô phỏng process.argv: ["node", "script.js", ...đối số]
function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const [k, v] = a.slice(2).split("=");
      out[k] = v === undefined ? true : v;
    } else out._.push(a);
  }
  return out;
}

console.log(JSON.stringify(parseArgs(["build", "--minify", "--out=dist"])));

